const fecha = $today.minus({ days: 1 }).toFormat('yyyy-MM-dd');

return [{
  json: {
    idEjecucion: String($execution.id),
    fechaDesde: fecha,
    fechaHasta: fecha,
    lotesEsperados: 26
  }
}];

const ejecucion = $('Inicializa Ejecucion').first().json;
const ID_COMPARTIDA = 2;

const sucursales = [
  { idSucursal: 6455, sucursalNombre: '01',                       idDivisionPropia: 1 },
  { idSucursal: 6457, sucursalNombre: '02 - Local de Rivadavia', idDivisionPropia: 3 },
  { idSucursal: 6084, sucursalNombre: '05 - Local de Monroe',    idDivisionPropia: 1 },
  { idSucursal: 6761, sucursalNombre: '11 - Local de Gallardo',  idDivisionPropia: 3 },
  { idSucursal: 6458, sucursalNombre: '16 - Local de Salguero',  idDivisionPropia: 1 },
  { idSucursal: 8774, sucursalNombre: '17 - Local de Boedo',     idDivisionPropia: 1 },
  { idSucursal: 9254, sucursalNombre: '18 - E-Commerce',         idDivisionPropia: 6 },
  { idSucursal: 9258, sucursalNombre: '20 - Local Membrillar',   idDivisionPropia: 3 },
  { idSucursal: 9261, sucursalNombre: '21 - Mayorista',          idDivisionPropia: 1 },
  { idSucursal: 9281, sucursalNombre: '23 - Local Plaza Italia', idDivisionPropia: 1 },
  { idSucursal: 9292, sucursalNombre: '24 - Local Doblas',       idDivisionPropia: 3 },
  { idSucursal: 9302, sucursalNombre: '25 - Local Beltran',      idDivisionPropia: 1 },
  { idSucursal: 9308, sucursalNombre: '26 - Local Parral',       idDivisionPropia: 1 }
];

const consultas = [];
for (const sucursal of sucursales) {
  for (const idDivision of [ID_COMPARTIDA, sucursal.idDivisionPropia]) {
    consultas.push({
      json: {
        idEjecucion: ejecucion.idEjecucion,
        fechaDesde: ejecucion.fechaDesde,
        fechaHasta: ejecucion.fechaHasta,
        idSucursal: sucursal.idSucursal,
        sucursalNombre: sucursal.sucursalNombre,
        idDivision
      }
    });
  }
}

return consultas;

const divisionMap = {
  1: 'Endron Empresa',
  2: 'Endron Prueba',
  3: 'Nich Empresa',
  6: 'Capay'
};

function sqlTexto(valor) {
  if (valor === null || valor === undefined) return 'NULL';
  return "'" + String(valor).replace(/'/g, "''") + "'";
}

function sqlJson(valor) {
  return "'" + JSON.stringify(valor).replace(/'/g, "''") + "'::jsonb";
}

const contexto = $('Normaliza Contexto').item.json;
const respuesta = $input.item.json.body ?? {};
const sociedad = divisionMap[contexto.idDivision] || `Division ${contexto.idDivision}`;

const query = `select * from centum_sync.ingestar_lote_ventas_v2(
  ${sqlTexto(contexto.idEjecucion)},
  ${Number(contexto.idDivision)},
  ${sqlTexto(sociedad)},
  ${Number(contexto.idSucursal)},
  ${sqlTexto(contexto.sucursalNombre)},
  ${sqlTexto(contexto.fechaDesde)}::date,
  ${sqlTexto(contexto.fechaHasta)}::date,
  ${sqlJson(respuesta)}
);`;

return [{ json: { query } }];
